contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address target, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value, "insufficient test balance");
        require(value <= address(c).balance, "value exceeds c's balance");
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;
        c.sendMoney(target, value, ""); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(afterC == beforeC - value && afterCount == beforeCount);
    }
}

